create table if not exists photo_evaluations (id uuid primary key default gen_random_uuid(), scene_snapshot jsonb not null default '{}', ranked_results jsonb not null default '[]', proactive_targets jsonb not null default '[]', limitations jsonb not null default '[]', metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists retail_price_snapshots (id uuid primary key default gen_random_uuid(), market char(2) not null, retailer text not null, category text not null, normal_price numeric(10,2) not null, strong_buy_price numeric(10,2), currency char(3) not null, observed_on date not null, source_url text, confidence text not null default 'medium', created_at timestamptz not null default now(), unique(market, retailer, category, observed_on));
create table if not exists target_snapshots (id uuid primary key default gen_random_uuid(), market char(2) not null, release_name text not null, rank integer not null, priority_score smallint not null check(priority_score between 0 and 100), decision text not null, observed_price numeric(10,2), currency char(3), snapshot_date date not null, provenance jsonb not null default '{}');
create table if not exists audit_events (id bigint generated always as identity primary key, actor text not null default 'system', action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
alter table collection_items add column if not exists purchase_currency char(3) not null default 'USD'; alter table collection_items add column if not exists evaluation_id uuid references photo_evaluations(id);
create index if not exists photo_evaluations_created_idx on photo_evaluations(created_at desc); create index if not exists target_market_rank_idx on target_snapshots(market, snapshot_date desc, rank); create index if not exists retail_market_date_idx on retail_price_snapshots(market, observed_on desc);
alter table sources enable row level security; alter table castings enable row level security; alter table releases enable row level security; alter table evaluations enable row level security; alter table collection_items enable row level security; alter table market_evidence enable row level security; alter table insights enable row level security; alter table photo_evaluations enable row level security; alter table retail_price_snapshots enable row level security; alter table target_snapshots enable row level security; alter table audit_events enable row level security;
-- No public policies by design. Server-only service role owns collection data.
